55	    @Override
56	    public JsonStructure read() {
57	        if (readDone) {
58	            throw new IllegalStateException(JsonMessages.READER_READ_ALREADY_CALLED());
59	        }
60	        readDone = true;
61	        if (parser.hasNext()) {
62	            try {
63	                JsonParser.Event e = parser.next();
64	                if (e == JsonParser.Event.START_ARRAY) {
65	                    return parser.getArray();
66	                } else if (e == JsonParser.Event.START_OBJECT) {
67	                    return parser.getObject();
68	                }
69	            } catch (IllegalStateException ise) {
70	                throw new JsonParsingException(ise.getMessage(), ise, parser.getLastCharLocation());
71	            }
72	        }
73	        throw new JsonException(JsonMessages.INTERNAL_ERROR());
74	    }
