76	    @Override
77	    public JsonObject readObject() {
78	        if (readDone) {
79	            throw new IllegalStateException(JsonMessages.READER_READ_ALREADY_CALLED());
80	        }
81	        readDone = true;
82	        if (parser.hasNext()) {
83	            try {
84	                parser.next();
85	                return parser.getObject();
86	            } catch (IllegalStateException ise) {
87	                throw new JsonParsingException(ise.getMessage(), ise, parser.getLastCharLocation());
88	            }
89	        }
90	        throw new JsonException(JsonMessages.INTERNAL_ERROR());
91	    }
92	
93	    @Override
94	    public JsonArray readArray() {
95	        if (readDone) {
96	            throw new IllegalStateException(JsonMessages.READER_READ_ALREADY_CALLED());
97	        }
98	        readDone = true;
99	        if (parser.hasNext()) {
100	            try {
101	                parser.next();
102	                return parser.getArray();
103	            } catch (IllegalStateException ise) {
104	                throw new JsonParsingException(ise.getMessage(), ise, parser.getLastCharLocation());
105	            }
106	        }
107	        throw new JsonException(JsonMessages.INTERNAL_ERROR());
108	    }
109	
110	    @Override
111	    public JsonValue readValue() {
112	        if (readDone) {
113	            throw new IllegalStateException(JsonMessages.READER_READ_ALREADY_CALLED());
114	        }
115	        readDone = true;
116	        if (parser.hasNext()) {
117	            try {
118	                parser.next();
119	                return parser.getValue();
120	            } catch (IllegalStateException ise) {
121	                throw new JsonParsingException(ise.getMessage(), ise, parser.getLastCharLocation());
122	            }
123	        }
124	        throw new JsonException(JsonMessages.INTERNAL_ERROR());
125	    }
126	
127	    @Override
128	    public void close() {
129	        readDone = true;
130	        parser.close();
131	    }
132	}
