240	    @Override
241	    public JsonGenerator write(JsonValue value) {
242	        checkContextForValue();
243	
244	        switch (value.getValueType()) {
245	            case ARRAY:
246	                JsonArray array = (JsonArray)value;
247	                writeStartArray();
248	                for(JsonValue child: array) {
249	                    write(child);
250	                }
251	                writeEnd();
252	                break;
253	            case OBJECT:
254	                JsonObject object = (JsonObject)value;
255	                writeStartObject();
256	                for(Map.Entry<String, JsonValue> member: object.entrySet()) {
257	                    write(member.getKey(), member.getValue());
258	                }
259	                writeEnd();
260	                break;
261	            case STRING:
262	                JsonString str = (JsonString)value;
263	                write(str.getString());
264	                break;
265	            case NUMBER:
266	                JsonNumber number = (JsonNumber)value;
267	                writeValue(number.toString());
268	                popFieldContext();
269	                break;
270	            case TRUE:
271	                write(true);
272	                break;
273	            case FALSE:
274	                write(false);
275	                break;
276	            case NULL:
277	                writeNull();
278	                break;
279	        }
