621	    // Not using Integer.toString() since it creates intermediary String
622	    // Also, we want the chars to be copied to our buffer directly
623	    void writeInt(int num) {
624	        int size;
625	        if (num == Integer.MIN_VALUE) {
626	            size = INT_MIN_VALUE_CHARS.length;
627	        } else {
628	            size = (num < 0) ? stringSize(-num) + 1 : stringSize(num);
629	        }
630	        if (len+size >= buf.length) {
631	            flushBuffer();
632	        }
633	        if (num == Integer.MIN_VALUE) {
634	            System.arraycopy(INT_MIN_VALUE_CHARS, 0, buf, len, size);
635	        } else {
636	            fillIntChars(num, buf, len+size);
637	        }
638	        len += size;
639	    }
