184	    private static Integer getIntSystemProperty(String propertyName) throws JsonException {
185	        String systemProperty = getSystemProperty(propertyName);
186	        if (systemProperty == null) {
187	            return null;
188	        }
189	        return propertyStringToInt(propertyName, systemProperty);
190	    }
