233	                case JsonConfig.REJECT_DUPLICATE_KEYS:
234	                    if (instance.rejectDuplicateKeys) {
235	                        newConfig.put(JsonConfig.REJECT_DUPLICATE_KEYS, true);
236	                    }
237	                // Rest of properties are copied without changes
238	                default:
239	                    if (config.containsKey(propertyName)) {
240	                        newConfig.put(propertyName, config.get(propertyName));
241	                    }
242	            }
243	        }
244	        return newConfig;
245	    }
